import Foundation

actor UsageCounter {
    private var total = 0

    func record() {
        total += 1
    }

    func count() -> Int {
        total
    }
}

@main
struct InventoryCLI {
    static func main() async {
        let counter = UsageCounter()
        await counter.record()
        let total = await counter.count()
        print("records: \(total)")
    }
}
